        public static string GetDamageIcon(DamageTypeEnum damageType)
        {
            return damageType switch
            {
                DamageTypeEnum.Bludgeoning or
                DamageTypeEnum.Bludgeoning_Silver or
                DamageTypeEnum.Bludgeoning_Magic => Bludgeoning,

                DamageTypeEnum.Piercing or
                DamageTypeEnum.Piercing_Silver or
                DamageTypeEnum.Piercing_Magic => Piercing,

                DamageTypeEnum.Slashing or
                DamageTypeEnum.Slashing_Silver or
                DamageTypeEnum.Slashing_Magic => Slashing,

                DamageTypeEnum.Acid => Acid,
                DamageTypeEnum.Cold => Cold,
                DamageTypeEnum.Fire => Fire,
                DamageTypeEnum.Force => Force,
                DamageTypeEnum.Lightning => Lightning,
                DamageTypeEnum.Necrotic => Necrotic,
                DamageTypeEnum.Poison => Poison,
                DamageTypeEnum.Psychic => Psychic,
                DamageTypeEnum.Radiant => Radiant,
                DamageTypeEnum.Thunder => Thunder,

                _ => string.Empty
            };
        }
    }
